package com.sumedha.commerce.product.repository; import com.sumedha.commerce.product.dto.request.ProductFilter; import com.sumedha.commerce.product.entity.Product; import jakarta.persistence.criteria.Predicate; import org.springframework.data.jpa.domain.Specification; import java.util.*; public final class ProductSpecifications {private ProductSpecifications(){}
public static Specification<Product> filterBy(ProductFilter filter){return (root,query,cb)->{List<Predicate> predicates=new ArrayList<>();if(filter.search()!=null&&!filter.search().isBlank())predicates.add(cb.like(cb.lower(root.get("name")),"%"+filter.search().toLowerCase(Locale.ROOT)+"%"));if(filter.categoryId()!=null)predicates.add(cb.equal(root.get("categoryId"),filter.categoryId()));if(filter.brandId()!=null)predicates.add(cb.equal(root.get("brandId"),filter.brandId()));if(filter.status()!=null)predicates.add(cb.equal(root.get("status"),filter.status()));if(filter.minPrice()!=null)predicates.add(cb.greaterThanOrEqualTo(root.get("price"),filter.minPrice()));if(filter.maxPrice()!=null)predicates.add(cb.lessThanOrEqualTo(root.get("price"),filter.maxPrice()));return cb.and(predicates.toArray(new Predicate[0]));};}}
